import React, { useState, memo, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { motion } from 'framer-motion';
import { ArrowRight, Gift, ExternalLink, X, Send, Phone, Mail, User } from 'lucide-react';
import PDFViewer from '../components/PDFViewer';
import { API_ENDPOINTS, getImageUrl } from '../config/api';

const Home = memo(() => {
  const [selectedCatalog, setSelectedCatalog] = useState(null);
  const [catalogs, setCatalogs] = useState([]);
  const [products, setProducts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [inquiryModal, setInquiryModal] = useState(false);
  const [inquiryCatalog, setInquiryCatalog] = useState(null);
  const [inquiryForm, setInquiryForm] = useState({
    catalogCode: '',
    catalogNumber: '',
    userName: '',
    userEmail: '',
    userPhone: '',
    message: ''
  });
  const [submittingInquiry, setSubmittingInquiry] = useState(false);
  const [inquirySuccess, setInquirySuccess] = useState(false);

  useEffect(() => {
    fetchDynamicData();
  }, []);

  const fetchDynamicData = async () => {
    try {
      // Fetch catalogs
      const catalogsRes = await fetch(API_ENDPOINTS.catalog);
      if (catalogsRes.ok) {
        const catalogsData = await catalogsRes.json();
        setCatalogs(catalogsData);
      }

      // Fetch products (using catalogs with type 'product')
      const productsRes = await fetch(API_ENDPOINTS.catalog);
      if (productsRes.ok) {
        const allData = await productsRes.json();
        setProducts(allData.filter(item => item.type === 'product'));
      }
    } catch (error) {
      console.error('Error fetching dynamic data:', error);
    } finally {
      setLoading(false);
    }
  };

  const featuredProducts = React.useMemo(() => products.filter(p => p.featured), [products]);

  const handleInquiryClick = (catalog) => {
    setInquiryCatalog(catalog);
    setInquiryModal(true);
    setInquirySuccess(false);
  };

  const handleInquirySubmit = async (e) => {
    e.preventDefault();
    setSubmittingInquiry(true);

    try {
      const response = await fetch(API_ENDPOINTS.catalogInquiry, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          catalogId: inquiryCatalog._id,
          catalogCode: inquiryForm.catalogCode,
          catalogNumber: inquiryForm.catalogNumber,
          userName: inquiryForm.userName,
          userEmail: inquiryForm.userEmail,
          userPhone: inquiryForm.userPhone,
          message: inquiryForm.message
        }),
      });

      const data = await response.json();

      if (response.ok) {
        setInquirySuccess(true);
        setInquiryForm({
          catalogCode: '',
          catalogNumber: '',
          userName: '',
          userEmail: '',
          userPhone: '',
          message: ''
        });
        setTimeout(() => {
          setInquiryModal(false);
          setInquirySuccess(false);
        }, 2000);
      } else {
        alert('Failed to submit inquiry. Please try again.');
      }
    } catch (error) {
      console.error('Error submitting inquiry:', error);
      alert('Network error. Please try again.');
    } finally {
      setSubmittingInquiry(false);
    }
  };

